@router.get("/api/v1/telemetry/devices/{device_uuid}/stream")
async def stream_device_telemetry(
    device_uuid: uuid.UUID,
    broker: TelemetryBroker = Depends(get_telemetry_broker),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    stmt = select(FleetDevice).where(
        FleetDevice.uuid == device_uuid,
        FleetDevice.owner_id == current_user.id
    )
    res = await db.execute(stmt)
    device = res.scalar_one_or_none()
    if not device:
        raise HTTPException(status_code=404, detail="Device not found or not owned by user")

    async def coordinate_emitter():
        queue = await broker.subscribe_telemetry(str(device_uuid))
        try:
            while True:
                reading = await queue.get()
                yield {"event": "metric", "data": json.dumps(reading)}
        finally:
            await broker.unsubscribe_telemetry(str(device_uuid), queue)

    return EventSourceResponse(coordinate_emitter())
